<?php
$term='%'.mb_substr((string)($_GET['q']??''),0,100).'%';$filter=(string)($_GET['filter']??'');$where='(p.name LIKE ? OR p.sku LIKE ?)';$args=[$term,$term];
$where.=match($filter){'low'=>' AND p.stock<=p.low_stock_threshold','reserved'=>' AND p.reserved>0','empty'=>' AND p.stock=0','unpriced'=>' AND p.purchase_price=0 AND (p.stock+p.reserved)>0',default=>''};
$stock=query("SELECT p.* FROM products p WHERE $where ORDER BY p.name",$args)->fetchAll();
?>
<div class="page-title"><div><p class="eyebrow">SKLADIŠNO POSLOVANJE</p><h1>Lager i rezervacije</h1><p>Slobodno + rezervisano = fizičko stanje. Svaka promjena ostaje evidentirana.</p></div><div class="action-group"><a class="btn secondary" href="?page=exits">Drugi izlazi robe ↗</a><?php if(can('print')):?><a class="btn secondary" href="?page=print&type=stock">Štampaj lagerlistu</a><?php endif;?><a class="btn" href="?page=reports&export=stock">Preuzmi CSV ↗</a></div></div>
<details class="panel stock-entry" <?=isset($_GET['entry'])?'open':''?>><summary><span>＋ Evidentiraj ulaz robe / pozitivnu korekciju</span><small>Za otpis, povlačenje i ličnu prodaju otvorite Drugi izlazi robe</small></summary><?php startForm('stock');?><div class="admin-filters"><div><?php $opts=[];foreach(query('SELECT * FROM products ORDER BY name')->fetchAll() as $p)$opts[$p['id']]=$p['sku'].' · '.$p['name'].' ('.$p['stock'].' slobodno)';selectField('id','Artikal',$opts);?></div><div><?php field('quantity','Količina ulaza (pozitivan broj)','','number');?></div><div><?php field('note','Dokument ili razlog promjene');?></div><button>Evidentiraj</button></div></form></details>
<section class="panel"><form method="get" class="admin-filters"><input type="hidden" name="page" value="inventory"><div><?php field('q','Naziv ili SKU',$_GET['q']??'','text',false);?></div><div><?php selectField('filter','Stanje',[''=>'Svi artikli','low'=>'Nizak lager','reserved'=>'Ima rezervacije','empty'=>'Bez slobodne zalihe','unpriced'=>'Nedostaje nabavna cijena'],$filter);?></div><button>Primijeni filter</button></form><div class="table-heading"><h2>Lagerlista</h2><span><?=count($stock)?> artikala</span></div><div class="table-scroll"><table><thead><tr><th>Artikal / SKU</th><th>Slobodno</th><th>Rezervisano</th><th>Fizički</th><th>Nabavna KM/kom.</th><th>Nabavna vrijednost</th><th>Stanje</th></tr></thead><tbody><?php foreach($stock as $p):?><tr><td><strong><?=e($p['name'])?></strong><small class="cell-note"><?=e($p['sku'])?></small></td><td class="numeric"><?=$p['stock']?></td><td class="numeric"><?=$p['reserved']?></td><td class="numeric"><?=(int)$p['stock']+(int)$p['reserved']?></td><td class="numeric"><?=money((float)$p['purchase_price'])?></td><td class="numeric"><?=money(((int)$p['stock']+(int)$p['reserved'])*(float)$p['purchase_price'])?></td><td><span class="status-badge <?=(int)$p['stock']<=(int)$p['low_stock_threshold']?'status-preparing':'status-completed'?>"><?=(int)$p['stock']<=(int)$p['low_stock_threshold']?'Za dopunu':'Dovoljno'?></span></td></tr><?php endforeach;if(!$stock):?><tr><td colspan="7" class="table-empty">Nema artikala za odabrani filter.</td></tr><?php endif;?></tbody></table></div><p class="field-help">Vrijednost koristi trenutnu nabavnu cijenu i uključuje rezervacije. Ovo je operativni prikaz, bez FIFO-a, ponderisane prosječne cijene i obračuna poreza.</p></section>
<section class="panel"><div class="section-heading"><div><p class="eyebrow">SLJEDIVOST ROBE</p><h2>Kartica prometa lagera</h2></div><a class="text-link" href="?page=reports">Filteri i puni CSV izvoz ↗</a></div><div class="table-scroll"><table><thead><tr><th>Datum</th><th>Artikal</th><th>Vrsta / dokument</th><th>Promjena slobodnog</th><th>Slobodno poslije</th><th>Rezervisano poslije</th><th>Operater</th></tr></thead><tbody><?php foreach(query('SELECT m.*,p.sku,u.name operator_name FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN users u ON u.id=m.user_id ORDER BY m.id DESC LIMIT 100')->fetchAll() as $m):?><tr><td class="nowrap"><?=e(date('d.m.Y. H:i',strtotime($m['created_at'])))?></td><td><?=e($m['sku'])?><?php if($m['order_id']):?><small class="cell-note">Narudžba #<?=$m['order_id']?></small><?php endif;?></td><td><?=e(movementLabel($m['kind']))?><small class="cell-note"><?=e($m['note'])?></small></td><td class="numeric"><?=$m['quantity']>0?'+':''?><?=$m['quantity']?></td><td class="numeric"><?=$m['available_after']??'—'?></td><td class="numeric"><?=$m['reserved_after']??'—'?></td><td><?=e($m['operator_name']??'Kupac / sistem')?></td></tr><?php endforeach;?></tbody></table></div><p class="field-help">Posljednjih 100 promjena. Za starije zapise stanje poslije promjene nije rekonstruisano.</p></section>
